#!/bin/sh
# SPDX-License-Identifier: GPL-2.0
# P4M software batch-start control board runner -- new-boot remaining29 segment.
#
# This file was generated by make_remaining29_runner.py from the frozen formal60
# delivery runner. The original source file is never modified: the generator
# reads it, performs fail-closed anchored substitutions and writes this
# independent copy. Every run_case/check_case_json/locate_*/verify_* and
# dmesg/JSON helper below is preserved byte-for-byte from that source.
#
# This is a USER-APPROVED NEW-BOOT INDEPENDENT GAP-FILL EXPERIMENT. It is NOT a
# same-boot continuation of the stopped formal60 run and it never claims the
# full 60-case run. The original resume35 seq37 anchor is deliberately unused
# and the old modes (short/compare/all/formal60/resume35) are unreachable: their
# functions may still be defined below but mode selection and dispatch accept
# ONLY "remaining29".
#
# Usage: linux_p4m_remaining29.sh MODE [OUTPUT_DIR]
#   MODE is required; the only accepted value is:
#     remaining29 29 P4M trials: the frozen formal60 remaining flat cases
#                 32..60 (formal-b11-g1000, formal-b11-g0, then b12..b20 in the
#                 original formal60 order), 4096 transfers, warmup 256,
#                 4096-byte chunk. Gap counts: 0:10, 1000:10, 2000:9.
#                 Requires the exact 00089 kernel revision, the boot_id fixed
#                 when this runner was generated, a first dmesg snapshot with
#                 startup_max_seq=0, taint 0 and path_observe Y.
#   OUTPUT_DIR must not already exist. Default: /tmp/p4m-start-$$.
#
# Pre-DMA gates, in order, before the first idma_experiment call:
#   * required commands present: platform-timeout idma_experiment dmesg uname awk
#   * uname -r / uname -a succeed
#   * uname -r does not match KERNEL_OLD_MATCH (the known old baseline revision)
#   * path_observe reads Y when the plan contains a --p4m case
#   * taint reads exactly 0
#   * remaining29 preflight (newboot_preflight), after the gates above and
#     before the first DMA:
#       - kernel_release exactly equals KERNEL_NEWBOOT_EXACT and contains 00089
#       - /proc/sys/kernel/random/boot_id equals NEWBOOT_BOOT_ID (generator arg)
#       - taint is exactly 0 and path_observe is Y
#       - the first dmesg snapshot has startup_max_seq=0 (no idma_batch_start
#         record at all this boot): any nonzero value means this is not a fresh
#         boot segment and the run stops for manual review
#     The preflight never reads or uses the original resume35 seq37 anchor.
#
# Per-trial gates and per-trial verification are exactly those of the frozen
# formal60 runner (taint 0 before/after, path_observe Y for --p4m, one new
# idma_batch_start with a strictly greater seq, one matching idma_batch_obs
# part=time record, the frozen startup/batch/JSON field contract). The first
# failure stops the run, exit 5 for a verification failure.
#
# Evidence kept for every trial even on failure (nothing is deleted):
#   <case>.json <case>.err <case>.dmesg.before <case>.dmesg.raw
#   <case>.startup <case>.batch_time
#   argv.txt input.txt matrix.txt params.txt path_observe.txt
#   remaining29-preflight.txt dmesg.raw dmesg.err taint.txt
#
# Exit codes:
#   0            clean complete
#   1..3         first CLI failure (CLI rc); 3 also for a taint/path_observe gate
#   4            capture/collection/output failure
#   5            per-trial or preflight verification failure
#   127          required command missing
#   129/130/143  HUP/INT/TERM signal
#   2            usage, fatal setup error or rejected kernel/uname
set -u

PATH=/sbin:/bin:/usr/sbin:/usr/bin
export PATH

TAINT_PATH=/proc/sys/kernel/tainted
OBSERVE_PATH=/sys/module/idma/parameters/observe
PATH_OBSERVE_PATH=/sys/module/idma/parameters/path_observe

# Known old baseline revision. Anything whose uname -r contains this is refused
# before any DMA because it predates the batch-start record.
KERNEL_OLD_MATCH=00088

# resume35 is intentionally narrower than formal60: it requires the exact fixed
# kernel revision and the archived seq37 boundary from the stopped original run.
KERNEL_RESUME_MATCH=00089
KERNEL_RESUME_EXACT=6.5.0-rc2-00089-gefd9461d6459
RESUME_ORIGINAL_ID=p4m-formal60-215406
RESUME_ORIGINAL=/tmp/p4m-formal60-215406
RESUME_ORIGINAL_CASE=formal-b09-g2000
RESUME_ANCHOR_SEQ=37
RESUME_ANCHOR_A_BEGIN_NS=3600085892000

# New-boot remaining29 segment constants. This segment runs on an independent
# fresh boot: the original resume35 seq37 anchor above is deliberately unused.
# The exact 00089 kernel revision and the generator-supplied boot_id are both
# required by newboot_preflight before the first DMA.
KERNEL_NEWBOOT_MATCH=00089
KERNEL_NEWBOOT_EXACT=6.5.0-rc2-00089-gefd9461d6459
NEWBOOT_BOOT_ID='e6d264eb-e2a2-43e8-8136-8a7e10363e56'
NEWBOOT_FIRST_STARTUP_MAX_SEQ=0

VICTIM_DEVICE=/dev/idma0
V_DID=10
A_DID=11
NO_AGGRESSOR=4294967295
CHUNK=4096
DRIVER_TIMEOUT_MS=60000
WATCHDOG=120

SHORT_TRANSFERS=64
SHORT_WARMUP=8
LONG_TRANSFERS=4096
LONG_WARMUP=256

usage() {
    cat <<'EOF'
Usage: linux_p4m_remaining29.sh MODE [OUTPUT_DIR]
  MODE is required; the only accepted value is:
    remaining29 29 P4M trials: frozen formal60 remaining flat cases 32..60
                (formal-b11-g1000, formal-b11-g0, then b12..b20 in the original
                formal60 order), 4096 transfers, warmup 256, 4096-byte chunk.
                Gap counts: 0:10, 1000:10, 2000:9. Requires the exact 00089
                kernel revision, the boot_id fixed when this runner was
                generated, a first dmesg snapshot with startup_max_seq=0,
                taint 0 and path_observe Y. Independent new boot; it does not
                reuse the original resume35 seq37 anchor and never claims the
                full 60-case run.
  OUTPUT_DIR must not already exist. Default: /tmp/p4m-start-$$.
  Every trial is wrapped in "platform-timeout 120" and uses --device /dev/idma0
  --victim-pages 1 --chunk 4096 --transfers 4096 --warmup 256 --timeout-ms 60000.
  No retry, no other benchmark, no FPGA or SD write; the first failure stops.
  Per-trial evidence is kept under OUTPUT_DIR even on failure.
EOF
}

fatal() {
    echo "P4M: fatal: $*" >&2
    exit 2
}

[ $# -ge 1 ] && [ $# -le 2 ] || { usage >&2; exit 2; }
mode=$1
case "$mode" in
    remaining29) TOTAL_CASES=29; plan_has_p4m=1 ;;
    *) usage >&2; exit 2 ;;
esac

if [ $# -eq 2 ]; then
    OUT=$2
else
    OUT=/tmp/p4m-start-$$
fi
[ -n "$OUT" ] || { usage >&2; exit 2; }
if [ -e "$OUT" ]; then
    fatal "output directory already exists: $OUT"
fi
mkdir "$OUT" || fatal "mkdir failed: $OUT"

read_taint() {
    if value=$(cat "$TAINT_PATH" 2>/dev/null); then
        case "$value" in
            ''|*[!0-9]*) echo unknown ;;
            *) echo "$value" ;;
        esac
    else
        echo unknown
    fi
}

read_observe() {
    if value=$(cat "$OBSERVE_PATH" 2>/dev/null); then
        case "$value" in
            Y|y) echo Y ;;
            N|n) echo N ;;
            *) echo unknown ;;
        esac
    else
        echo unknown
    fi
}

read_path_observe() {
    if value=$(cat "$PATH_OBSERVE_PATH" 2>/dev/null); then
        case "$value" in
            Y|y) echo Y ;;
            N|n) echo N ;;
            *) echo unknown ;;
        esac
    else
        echo unknown
    fi
}

save_dmesg() {
    dmesg > "$OUT/dmesg.raw" 2> "$OUT/dmesg.err"
    dmesg_rc=$?
    if [ "$dmesg_rc" -eq 0 ]; then
        emit_rc=0
        echo "P4M: dmesg.raw begin" >&2 || emit_rc=1
        cat "$OUT/dmesg.raw" >&2 || emit_rc=1
        echo "P4M: dmesg.raw end" >&2 || emit_rc=1
        if [ "$emit_rc" -ne 0 ]; then
            echo "P4M: dmesg.raw cat failed" >&2
            return 4
        fi
        return 0
    fi
    echo "dmesg collection failed rc=$dmesg_rc" > "$OUT/dmesg.error"
    echo "P4M: dmesg collection failed rc=$dmesg_rc" >&2
    echo "P4M: dmesg.raw begin (partial)" >&2
    cat "$OUT/dmesg.raw" >&2 2>/dev/null || echo "P4M: dmesg.raw cat failed" >&2
    echo "P4M: dmesg.raw end (partial)" >&2
    if [ -s "$OUT/dmesg.err" ]; then
        echo "P4M: dmesg.err begin" >&2
        cat "$OUT/dmesg.err" >&2 2>/dev/null || echo "P4M: dmesg.err cat failed" >&2
        echo "P4M: dmesg.err end" >&2
    fi
    return "$dmesg_rc"
}

save_taint() {
    final_taint=$(read_taint)
    if ! echo "$final_taint" > "$OUT/taint.txt"; then
        echo "P4M: taint write failed" >&2
        return 1
    fi
    echo "P4M: final_taint=$final_taint" >&2
    if [ "$final_taint" != "0" ]; then
        echo "P4M: final taint not clean (value=$final_taint)" >&2
        return 1
    fi
    return 0
}

# condition -> "<kind> <mode> <extra args>"
# kind: solo | pair (pair = an aggressor is configured)
# mode: p4m | batch (batch = ordinary --batch, no P4M bank)
condition_spec() {
    case "$1" in
        S)       echo "solo p4m --p4m --aggressor none --a-gap-cycles 0" ;;
        P1g0)    echo "pair p4m --p4m --aggressor 1 --aggressor-pages 1 --a-gap-cycles 0" ;;
        P8g0)    echo "pair p4m --p4m --aggressor 1 --aggressor-pages 8 --a-gap-cycles 0" ;;
        P8g1000) echo "pair p4m --p4m --aggressor 1 --aggressor-pages 8 --a-gap-cycles 1000" ;;
        P8g2000) echo "pair p4m --p4m --aggressor 1 --aggressor-pages 8 --a-gap-cycles 2000" ;;
        B8)      echo "pair batch --batch --aggressor 1 --aggressor-pages 8" ;;
        *)       return 1 ;;
    esac
    return 0
}

# Strip one surrounding pair of double quotes from a JSON string scalar.
unquote() {
    uq_value=$1
    case "$uq_value" in
        \"*\") uq_value=${uq_value#\"}; uq_value=${uq_value%\"} ;;
    esac
    printf '%s\n' "$uq_value"
}

# Print the decimal integer form of a scalar, accepting 0x-prefixed hex.
# Prints MISSING when the scalar is not an integer.
int_of() {
    awk -v s="$1" '
    function hex2dec(h,   i, n, c, d, v) {
        n = length(h); v = 0
        for (i = 1; i <= n; i++) {
            c = substr(h, i, 1)
            if (c >= "0" && c <= "9") d = c + 0
            else if (c >= "a" && c <= "f") d = index("abcdef", c) + 9
            else if (c >= "A" && c <= "F") d = index("ABCDEF", c) + 9
            else return "MISSING"
            v = v * 16 + d
        }
        return v
    }
    BEGIN {
        if (s ~ /^-?[0-9]+$/) { printf "%.0f\n", s + 0; exit 0 }
        if (s ~ /^0x[0-9a-fA-F]+$/) { printf "%.0f\n", hex2dec(substr(s, 3)); exit 0 }
        if (s ~ /^-0x[0-9a-fA-F]+$/) { printf "-%.0f\n", hex2dec(substr(s, 4)); exit 0 }
        print "MISSING"
    }
    '
}

# Narrow dotted-path JSON scalar reader for the frozen CLI output. This is
# deliberately NOT a general JSON parser: it returns only a scalar (string with
# quotes kept, or number/literal text) found at a depth 1..N key path, and never
# returns an object or array. MISSING is printed when the path is absent or the
# value is composite. It is bounded and BusyBox-awk compatible.
json_get() {
    awk -v path="$2" '
    function scalar(j,   ch, v, c2) {
        if (j > N) { VALUE = "MISSING"; return j }
        while (j <= N && (substr(text, j, 1) == " " || substr(text, j, 1) == "\t")) j++
        if (j > N) { VALUE = "MISSING"; return j }
        ch = substr(text, j, 1)
        if (ch == "\"") {
            v = "\""; j++
            while (j <= N) {
                c2 = substr(text, j, 1)
                if (c2 == "\\") { v = v c2 substr(text, j + 1, 1); j += 2; continue }
                v = v c2
                if (c2 == "\"") { j++; break }
                j++
            }
            VALUE = v
            return j
        }
        v = ""
        while (j <= N) {
            c2 = substr(text, j, 1)
            if (c2 == "," || c2 == "}" || c2 == "]" || c2 == " " || c2 == "\t") break
            v = v c2; j++
        }
        VALUE = v
        return j
    }
    BEGIN {
        ncomp = split(path, comp, ".")
        for (i = 1; i <= ncomp; i++) want[i] = comp[i]
    }
    { text = text " " $0 }
    END {
        N = length(text)
        depth = 0; instr = 0; esc = 0
        for (i = 1; i <= N; i++) {
            c = substr(text, i, 1)
            if (instr) {
                if (esc) { esc = 0; continue }
                if (c == "\\") { esc = 1; continue }
                if (c != "\"") continue
                instr = 0
                j = i + 1
                while (j <= N && substr(text, j, 1) == " ") j++
                if (j > N || substr(text, j, 1) != ":") continue
                key = substr(text, s_start + 1, i - s_start - 1)
                kpath[depth] = key
                if (depth == ncomp) {
                    ok = 1
                    for (m = 1; m < ncomp; m++)
                        if (kpath[m] != want[m]) { ok = 0; break }
                    if (ok && key == want[ncomp]) {
                        scalar(j + 1)
                        print VALUE
                        exit 0
                    }
                }
                continue
            }
            if (c == "\"") { instr = 1; s_start = i; continue }
            if (c == "{" || c == "[") { depth++; continue }
            if (c == "}" || c == "]") { depth--; continue }
        }
        print "MISSING"
    }
    ' "$1"
}

# Print the value of a key=token in an extracted single-record file, or fail.
dmget() {
    awk -v k="$2" '
    {
        n = split($0, tok, "[ \t]+")
        for (i = 1; i <= n; i++) {
            t = tok[i]
            p = index(t, "=")
            if (p > 1 && !found && substr(t, 1, p - 1) == k) { v = substr(t, p + 1); found = 1 }
        }
    }
    END { if (found) print v; else exit 1 }' "$1"
}

# Maximum seq= among valid idma_batch_start records in a dmesg snapshot.
# Prints 0 when the snapshot has no startup records (valid first boot).
# Fails closed (nonzero, verify_failed on stderr) if a startup record lacks a
# well-formed seq=<digits> field or the file cannot be read.
startup_max_seq() {
    awk -v id="$2" '
    function fail(m) { printf "P4M: case=%s verify_failed=%s\n", id, m; bad = 1 }
    /idma_batch_start / {
        s = ""
        for (i = 1; i <= NF; i++)
            if ($i ~ /^seq=[0-9]+$/) { s = substr($i, 5) + 0; break }
        if (s == "") { fail("startup_seq_invalid"); next }
        if (s > m) m = s
    }
    END {
        if (bad) exit 1
        print m + 0
    }' "$1"
}

# Print the seq= of the (single) startup line in the given file.
startup_seq() {
    awk '
    /idma_batch_start / {
        for (i = 1; i <= NF; i++)
            if ($i ~ /^seq=[0-9]+$/) { print substr($i, 5); exit }
    }' "$1"
}

# Require exactly one NEW startup record whose seq is strictly greater than every
# valid seq seen before the run, and extract it. The total startup line count is
# not required to grow: a ring-buffer rotation that drops an old record while
# adding the new latest seq is valid. A counted-but-reused seq, duplicate new
# seq, multiple new seqs, missing record, malformed seq field or unreadable
# snapshot fails closed. An empty before snapshot is valid (first boot seq 1).
locate_new_startup() {
    lns_id=$1
    lns_before=$2
    lns_after=$3
    lns_dest=$4

    if [ ! -r "$lns_before" ]; then
        echo "P4M: case=$lns_id verify_failed=startup_before_unreadable file=$lns_before" >&2
        return 1
    fi
    if [ ! -r "$lns_after" ]; then
        echo "P4M: case=$lns_id verify_failed=startup_after_unreadable file=$lns_after" >&2
        return 1
    fi

    lns_max_before=$(startup_max_seq "$lns_before" "$lns_id")
    lns_max_rc=$?
    if [ "$lns_max_rc" -ne 0 ]; then
        if [ -n "$lns_max_before" ]; then
            printf '%s\n' "$lns_max_before" >&2
        else
            echo "P4M: case=$lns_id verify_failed=startup_max_seq_unreadable file=$lns_before" >&2
        fi
        return 1
    fi
    case "$lns_max_before" in
        ''|*[!0-9]*)
            echo "P4M: case=$lns_id verify_failed=startup_max_seq_unreadable file=$lns_before" >&2
            return 1 ;;
    esac

    lns_line=$(awk -v id="$lns_id" -v mx="$lns_max_before" '
    function fail(m) { printf "P4M: case=%s verify_failed=%s\n", id, m; bad = 1 }
    /idma_batch_start / {
        s = ""
        for (i = 1; i <= NF; i++)
            if ($i ~ /^seq=[0-9]+$/) { s = substr($i, 5) + 0; break }
        if (s == "") { fail("startup_seq_invalid"); next }
        if (s > mx) { n++; last = $0 }
    }
    END {
        if (bad) exit 2
        if (n != 1) {
            printf "P4M: case=%s verify_failed=startup_new_count want=1 got=%d before_max_seq=%d\n", id, n + 0, mx
            exit 1
        }
        print last
    }' "$lns_after")
    lns_rc=$?
    if [ "$lns_rc" -ne 0 ]; then
        if [ -n "$lns_line" ]; then
            printf '%s\n' "$lns_line" >&2
        else
            echo "P4M: case=$lns_id verify_failed=startup_line_extract file=$lns_after" >&2
        fi
        return 1
    fi
    if [ -z "$lns_line" ]; then
        echo "P4M: case=$lns_id verify_failed=startup_line_extract file=$lns_after" >&2
        return 1
    fi
    if ! printf '%s\n' "$lns_line" > "$lns_dest"; then
        echo "P4M: case=$lns_id verify_failed=startup_line_extract file=$lns_dest" >&2
        return 1
    fi
    return 0
}

# Require exactly one idma_batch_obs part=time record with the startup seq in
# the after snapshot, and none with that seq in the before snapshot.
locate_new_batch_time() {
    lnb_id=$1
    lnb_before=$2
    lnb_after=$3
    lnb_seq=$4
    lnb_dest=$5

    lnb_n_before=$(awk -v s="$lnb_seq" '
        /idma_batch_obs / && /part=time/ {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) n++
        }
        END { print n + 0 }' "$lnb_before")
    if [ "$lnb_n_before" != "0" ]; then
        echo "P4M: case=$lnb_id verify_failed=batch_time_seq_present_before seq=$lnb_seq got=$lnb_n_before" >&2
        return 1
    fi
    lnb_n=$(awk -v s="$lnb_seq" '
        /idma_batch_obs / && /part=time/ {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) n++
        }
        END { print n + 0 }' "$lnb_after")
    if [ "$lnb_n" != "1" ]; then
        echo "P4M: case=$lnb_id verify_failed=batch_time_count seq=$lnb_seq want=1 got=$lnb_n" >&2
        return 1
    fi
    if ! awk -v s="$lnb_seq" '
        /idma_batch_obs / && /part=time/ {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) { print $0; exit }
        }' "$lnb_after" > "$lnb_dest"; then
        echo "P4M: case=$lnb_id verify_failed=batch_time_extract seq=$lnb_seq" >&2
        return 1
    fi
    return 0
}

# Validate the new batch-start record against the frozen log contract.
# Prints a canonical field summary on success; prints verify_failed lines and
# returns 1 on any mismatch. a_id/v_id are mandatory: solo must report a_id=0,
# pair must report a_id>0 and v_id>0.
verify_startup() {
    vs_id=$1
    vs_file=$2
    vs_kind=$3

    vs_out=$(awk -v id="$vs_id" -v kind="$vs_kind" '
    function fail(m) { printf "P4M: case=%s verify_failed=%s\n", id, m; bad = 1 }
    function isint(s) { return s ~ /^-?[0-9]+$/ }
    BEGIN {
        nreq = split("version seq method v_did a_did attempted has_a a_triggered v_triggered a_id v_id a_begin_ns a_end_ns v_begin_ns v_end_ns irq_span_ns a_to_v_ns error", req, " ")
        for (i = 1; i <= nreq; i++) need[req[i]] = 1
    }
    {
        if ($0 !~ /idma_batch_start version=1 seq=/) fail("startup_prefix_not_found")
        n = split($0, tok, "[ \t]+")
        for (i = 1; i <= n; i++) {
            t = tok[i]
            p = index(t, "=")
            if (p > 1 && substr(t, 1, p - 1) ~ /^[A-Za-z_][A-Za-z0-9_]*$/)
                val[substr(t, 1, p - 1)] = substr(t, p + 1)
        }
        lines++
    }
    END {
        if (lines == 0) { fail("startup_line_empty"); exit 5 }
        for (k in need) {
            if (!(k in val)) { fail("field_missing_" k); continue }
            if (k == "method") {
                if (val[k] != "irq_pair") fail("method_not_irq_pair")
                continue
            }
            if (!isint(val[k])) fail("field_not_integer_" k)
        }
        if (bad) exit 5
        if (val["version"] + 0 != 1) fail("version_not_1")
        if (val["attempted"] + 0 != 1) fail("attempted_not_1")
        if (val["error"] + 0 != 0) fail("error_not_0")
        if (val["v_triggered"] + 0 != 1) fail("v_triggered_not_1")
        if (val["v_did"] != "10") fail("v_did_not_10")
        if (val["seq"] + 0 <= 0) fail("seq_not_positive")
        if (val["v_id"] + 0 <= 0) fail("v_id_not_positive")
        if (val["v_begin_ns"] + 0 <= 0) fail("v_begin_ns_not_positive")
        if (val["v_end_ns"] + 0 < val["v_begin_ns"] + 0) fail("v_time_order")
        if (val["irq_span_ns"] + 0 <= 0) fail("irq_span_ns_not_positive")
        if (kind == "solo") {
            if (val["a_did"] != "4294967295") fail("solo_a_did_not_no_aggressor")
            if (val["has_a"] + 0 != 0) fail("solo_has_a_not_0")
            if (val["a_triggered"] + 0 != 0) fail("solo_a_triggered_not_0")
            if (val["a_id"] + 0 != 0) fail("solo_a_id_not_0")
            if (val["a_begin_ns"] + 0 != 0) fail("solo_a_begin_ns_not_0")
            if (val["a_end_ns"] + 0 != 0) fail("solo_a_end_ns_not_0")
            if (val["a_to_v_ns"] + 0 != 0) fail("solo_a_to_v_ns_not_0")
            if (val["irq_span_ns"] + 0 != val["v_end_ns"] + 0 - val["v_begin_ns"] + 0) fail("solo_irq_span_mismatch")
        } else {
            if (val["a_did"] != "11") fail("pair_a_did_not_11")
            if (val["has_a"] + 0 != 1) fail("pair_has_a_not_1")
            if (val["a_triggered"] + 0 != 1) fail("pair_a_triggered_not_1")
            if (val["a_id"] + 0 <= 0) fail("pair_a_id_not_positive")
            if (val["a_begin_ns"] + 0 <= 0) fail("pair_a_begin_ns_not_positive")
            if (val["a_end_ns"] + 0 < val["a_begin_ns"] + 0) fail("pair_a_time_order")
            if (val["v_begin_ns"] + 0 < val["a_end_ns"] + 0) fail("pair_a_end_after_v_begin")
            if (val["a_to_v_ns"] + 0 != val["v_begin_ns"] + 0 - val["a_begin_ns"] + 0) fail("pair_a_to_v_ns_mismatch")
            if (val["irq_span_ns"] + 0 != val["v_end_ns"] + 0 - val["a_begin_ns"] + 0) fail("pair_irq_span_mismatch")
        }
        if (bad) exit 5
        printf "version=%s seq=%s method=%s v_did=%s a_did=%s attempted=%s has_a=%s a_triggered=%s v_triggered=%s a_id=%s v_id=%s a_begin_ns=%s a_end_ns=%s v_begin_ns=%s v_end_ns=%s irq_span_ns=%s a_to_v_ns=%s error=%s\n", val["version"], val["seq"], val["method"], val["v_did"], val["a_did"], val["attempted"], val["has_a"], val["a_triggered"], val["v_triggered"], val["a_id"], val["v_id"], val["a_begin_ns"], val["a_end_ns"], val["v_begin_ns"], val["v_end_ns"], val["irq_span_ns"], val["a_to_v_ns"], val["error"]
    }
    ' "$vs_file")

    vs_rc=$?
    if [ "$vs_rc" -ne 0 ] || [ -z "$vs_out" ]; then
        if [ -z "$vs_out" ]; then
            echo "P4M: case=$vs_id verify_failed=startup_record_unreadable file=$vs_file" >&2
        else
            printf '%s\n' "$vs_out" >&2
        fi
        return 1
    fi
    printf '%s\n' "$vs_out"
    return 0
}

# Validate the new part=time batch record: the hardware window that belongs to
# this trial's own seq.
verify_batch_time() {
    vbt_id=$1
    vbt_file=$2
    vbt_transfers=$3
    vbt_a_did=$4

    vbt_v=$(int_of "$(dmget "$vbt_file" valid)")
    if [ "$vbt_v" != "1" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_valid_not_1 got=$vbt_v" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" status)")
    if [ "$vbt_v" != "4" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_status_not_4 got=$vbt_v" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" v_did)")
    if [ "$vbt_v" != "$V_DID" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_v_did got=$vbt_v want=$V_DID" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" a_did)")
    if [ "$vbt_v" != "$vbt_a_did" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_a_did got=$vbt_v want=$vbt_a_did" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" issued)")
    if [ "$vbt_v" != "$vbt_transfers" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_issued got=$vbt_v want=$vbt_transfers" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" done)")
    if [ "$vbt_v" != "$vbt_transfers" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_done got=$vbt_v want=$vbt_transfers" >&2
        return 1
    fi
    vbt_v=$(int_of "$(dmget "$vbt_file" batch_polled)")
    if [ "$vbt_v" != "1" ]; then
        echo "P4M: case=$vbt_id verify_failed=batch_time_batch_polled_not_1 got=$vbt_v" >&2
        return 1
    fi
    return 0
}

# Normalize the scalar at a dotted JSON key path and require it to equal want.
json_check() {
    jk_id=$1
    jk_file=$2
    jk_key=$3
    jk_want=$4
    jk_got=$(int_of "$(unquote "$(json_get "$jk_file" "$jk_key")")")
    if [ "$jk_got" != "$jk_want" ]; then
        echo "P4M: case=$jk_id verify_failed=json_${jk_key} got=$jk_got want=$jk_want" >&2
        return 1
    fi
    return 0
}

# Narrow CLI JSON checks against the frozen nested schema. Values are read from
# their real locations: top-level success, the nested result object, and (for
# --p4m) the nested p4m object. There is no top-level batch_polled/status/
# v_issued/time_valid. Opening ids and A progress are never compared.
check_case_json() {
    ccj_id=$1
    ccj_file=$2
    ccj_mode=$3
    ccj_transfers=$4
    ccj_a_did=$5
    ccj_seq=$6

    if [ ! -s "$ccj_file" ]; then
        echo "P4M: case=$ccj_id verify_failed=cli_json_missing_or_empty file=$ccj_file" >&2
        return 1
    fi
    ccj_v=$(unquote "$(json_get "$ccj_file" success)")
    if [ "$ccj_v" != "true" ]; then
        echo "P4M: case=$ccj_id verify_failed=json_success_not_true got=$ccj_v" >&2
        return 1
    fi
    json_check "$ccj_id" "$ccj_file" result.status 0 || return 1
    json_check "$ccj_id" "$ccj_file" result.hpm_configured 1 || return 1
    json_check "$ccj_id" "$ccj_file" result.measurement_started 1 || return 1
    json_check "$ccj_id" "$ccj_file" result.measurement_complete 1 || return 1
    json_check "$ccj_id" "$ccj_file" result.victim_did "$V_DID" || return 1
    json_check "$ccj_id" "$ccj_file" result.victim.submitted "$ccj_transfers" || return 1
    json_check "$ccj_id" "$ccj_file" result.victim.completed "$ccj_transfers" || return 1
    json_check "$ccj_id" "$ccj_file" result.victim.data_errors 0 || return 1
    json_check "$ccj_id" "$ccj_file" result.victim.quarantined 0 || return 1
    if [ "$ccj_a_did" = "$A_DID" ]; then
        json_check "$ccj_id" "$ccj_file" result.aggressor_did "$A_DID" || return 1
        json_check "$ccj_id" "$ccj_file" result.aggressor.data_errors 0 || return 1
        json_check "$ccj_id" "$ccj_file" result.aggressor.quarantined 0 || return 1
    fi
    if [ "$ccj_mode" = "p4m" ]; then
        json_check "$ccj_id" "$ccj_file" p4m.observer_status 4 || return 1
        json_check "$ccj_id" "$ccj_file" p4m.v_issued "$ccj_transfers" || return 1
        json_check "$ccj_id" "$ccj_file" p4m.v_done "$ccj_transfers" || return 1
        json_check "$ccj_id" "$ccj_file" p4m.sequence "$ccj_seq" || return 1
    fi
    return 0
}

run_case() {
    rc_id=$1
    rc_cond=$2
    rc_transfers=$3
    rc_warmup=$4

    if ! rc_spec=$(condition_spec "$rc_cond"); then
        echo "P4M: internal error unknown condition=$rc_cond" >&2
        return 2
    fi
    rc_kind=${rc_spec%% *}
    rc_rest=${rc_spec#* }
    rc_mode=${rc_rest%% *}
    rc_extra=${rc_rest#* }
    if [ "$rc_kind" = "solo" ]; then
        rc_a_did=$NO_AGGRESSOR
    else
        rc_a_did=$A_DID
    fi

    rc_json="$OUT/$rc_id.json"
    rc_err="$OUT/$rc_id.err"
    rc_before="$OUT/$rc_id.dmesg.before"
    rc_after="$OUT/$rc_id.dmesg.raw"
    rc_startup="$OUT/$rc_id.startup"
    rc_batchtime="$OUT/$rc_id.batch_time"

    rc_common="--device $VICTIM_DEVICE --victim-pages 1 --chunk $CHUNK --transfers $rc_transfers --warmup $rc_warmup --timeout-ms $DRIVER_TIMEOUT_MS"
    rc_argv="platform-timeout $WATCHDOG idma_experiment $rc_common $rc_extra"

    rc_before_taint=$(read_taint)
    rc_observe=$(read_observe)
    rc_path_observe=$(read_path_observe)
    if ! printf '%s observe=%s path_observe=%s\n' "$rc_id" "$rc_observe" "$rc_path_observe" >> "$OUT/path_observe.txt"; then
        echo "P4M: case=$rc_id observe_record_failed" >&2
        return 4
    fi

    if [ "$rc_before_taint" != "0" ]; then
        echo "P4M: case=$rc_id gate=taint_before value=$rc_before_taint refusing to run" >&2
        return 3
    fi
    if [ "$rc_mode" = "p4m" ] && [ "$rc_path_observe" != "Y" ]; then
        echo "P4M: case=$rc_id gate=path_observe value=$rc_path_observe refusing to run (--p4m case requires Y)" >&2
        return 3
    fi

    if ! dmesg > "$rc_before" 2> "$OUT/$rc_id.dmesg.before.err"; then
        echo "P4M: case=$rc_id collection=dmesg_before_failed" >&2
        return 4
    fi

    if ! printf 'id=%s condition=%s kind=%s mode=%s transfers=%s warmup=%s argv=%s\n' \
            "$rc_id" "$rc_cond" "$rc_kind" "$rc_mode" "$rc_transfers" "$rc_warmup" "$rc_argv" \
            >> "$OUT/argv.txt"; then
        echo "P4M: case=$rc_id argv_record_failed" >&2
        return 4
    fi

    echo "P4M: case_begin id=$rc_id condition=$rc_cond kind=$rc_kind mode=$rc_mode taint_before=$rc_before_taint observe=$rc_observe path_observe=$rc_path_observe total=$TOTAL_CASES argv=$rc_argv" >&2

    # shellcheck disable=SC2086
    platform-timeout "$WATCHDOG" idma_experiment $rc_common $rc_extra > "$rc_json" 2> "$rc_err"
    rc_rc=$?
    rc_after_taint=$(read_taint)

    rc_cat_failed=0
    echo "P4M: case_stdout_begin id=$rc_id" >&2
    cat "$rc_json" || { echo "P4M: case_stdout_cat_failed id=$rc_id" >&2; rc_cat_failed=1; }
    echo "P4M: case_stdout_end id=$rc_id" >&2

    echo "P4M: case_stderr_begin id=$rc_id" >&2
    if [ -s "$rc_err" ]; then
        cat "$rc_err" >&2 || { echo "P4M: case_stderr_cat_failed id=$rc_id" >&2; rc_cat_failed=1; }
    fi
    echo "P4M: case_stderr_end id=$rc_id" >&2

    if ! dmesg > "$rc_after" 2> "$OUT/$rc_id.dmesg.err"; then
        echo "P4M: case=$rc_id collection=dmesg_after_failed" >&2
        return 4
    fi
    echo "P4M: dmesg.raw_begin id=$rc_id" >&2
    cat "$rc_after" >&2 || { echo "P4M: dmesg.raw_cat_failed id=$rc_id" >&2; rc_cat_failed=1; }
    echo "P4M: dmesg.raw_end id=$rc_id" >&2

    echo "P4M: case_exit id=$rc_id exit=$rc_rc taint_after=$rc_after_taint" >&2

    if [ "$rc_rc" -ne 0 ]; then
        echo "P4M: case_failed id=$rc_id exit=$rc_rc" >&2
        return "$rc_rc"
    fi
    if [ "$rc_cat_failed" -ne 0 ]; then
        echo "P4M: case=$rc_id collection=emit_failed" >&2
        return 4
    fi
    if [ "$rc_after_taint" != "0" ]; then
        echo "P4M: case=$rc_id gate=taint_after value=$rc_after_taint stopping" >&2
        return 3
    fi

    if ! locate_new_startup "$rc_id" "$rc_before" "$rc_after" "$rc_startup"; then
        return 5
    fi
    rc_seq=$(startup_seq "$rc_startup")
    case "$rc_seq" in
        ''|*[!0-9]*)
            echo "P4M: case=$rc_id verify_failed=startup_seq_unreadable file=$rc_startup" >&2
            return 5 ;;
    esac

    if ! locate_new_batch_time "$rc_id" "$rc_before" "$rc_after" "$rc_seq" "$rc_batchtime"; then
        return 5
    fi
    if ! rc_sfields=$(verify_startup "$rc_id" "$rc_startup" "$rc_kind"); then
        return 5
    fi
    echo "P4M: case_startup id=$rc_id $rc_sfields" >&2
    if ! verify_batch_time "$rc_id" "$rc_batchtime" "$rc_transfers" "$rc_a_did"; then
        return 5
    fi
    if ! check_case_json "$rc_id" "$rc_json" "$rc_mode" "$rc_transfers" "$rc_a_did" "$rc_seq"; then
        return 5
    fi

    cases_done=$((cases_done + 1))
    echo "P4M: case_end id=$rc_id exit=0 cases_done=$cases_done total=$TOTAL_CASES" >&2
    return 0
}

run_short_block() {
    run_case "start-s1-solo" S "$SHORT_TRANSFERS" "$SHORT_WARMUP" || return $?
    run_case "start-s2-a1-gap0" P1g0 "$SHORT_TRANSFERS" "$SHORT_WARMUP" || return $?
    run_case "start-s3-a8-gap0" P8g0 "$SHORT_TRANSFERS" "$SHORT_WARMUP" || return $?
    run_case "start-s4-a8-gap1000" P8g1000 "$SHORT_TRANSFERS" "$SHORT_WARMUP" || return $?
    return 0
}

run_compare_block() {
    run_case "start-c1-b8" B8 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c2-p8g0" P8g0 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c3-p8g0" P8g0 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c4-b8" B8 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c5-b8" B8 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c6-p8g0" P8g0 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c7-p8g0" P8g0 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "start-c8-b8" B8 "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    return 0
}

run_formal_triplet() {
    rft_block=$1
    rft_g1=$2
    rft_g2=$3
    rft_g3=$4

    run_case "formal-b${rft_block}-g${rft_g1}" "P8g${rft_g1}" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b${rft_block}-g${rft_g2}" "P8g${rft_g2}" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b${rft_block}-g${rft_g3}" "P8g${rft_g3}" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    return 0
}

run_formal_block() {
    run_formal_triplet 01 0 1000 2000 || return $?
    run_formal_triplet 02 1000 2000 0 || return $?
    run_formal_triplet 03 2000 0 1000 || return $?
    run_formal_triplet 04 0 2000 1000 || return $?
    run_formal_triplet 05 2000 1000 0 || return $?
    run_formal_triplet 06 1000 0 2000 || return $?
    run_formal_triplet 07 0 1000 2000 || return $?
    run_formal_triplet 08 1000 2000 0 || return $?
    run_formal_triplet 09 2000 0 1000 || return $?
    run_formal_triplet 10 0 2000 1000 || return $?
    run_formal_triplet 11 2000 1000 0 || return $?
    run_formal_triplet 12 1000 0 2000 || return $?
    run_formal_triplet 13 0 1000 2000 || return $?
    run_formal_triplet 14 1000 2000 0 || return $?
    run_formal_triplet 15 2000 0 1000 || return $?
    run_formal_triplet 16 0 2000 1000 || return $?
    run_formal_triplet 17 2000 1000 0 || return $?
    run_formal_triplet 18 1000 0 2000 || return $?
    run_formal_triplet 19 0 1000 2000 || return $?
    run_formal_triplet 20 2000 1000 0 || return $?
    return 0
}

# Extract the unique idma_batch_start seq=37 and the matching
# idma_batch_obs part=time seq=37 record from a dmesg snapshot. This is a
# read-only helper for the resume35 preflight; the source file is never edited.
extract_resume_seq37() {
    ers_id=$1
    ers_src=$2
    ers_startup=$3
    ers_batchtime=$4

    if [ ! -r "$ers_src" ]; then
        echo "P4M: resume=$ers_id preflight_failed=unreadable_dmesg file=$ers_src" >&2
        return 1
    fi

    ers_n_start=$(awk -v s="$RESUME_ANCHOR_SEQ" '
        /idma_batch_start / {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) n++
        }
        END { print n + 0 }' "$ers_src")
    case "$ers_n_start" in
        ''|*[!0-9]*)
            echo "P4M: resume=$ers_id preflight_failed=seq37_startup_count_unreadable file=$ers_src" >&2
            return 1 ;;
    esac
    if [ "$ers_n_start" != "1" ]; then
        echo "P4M: resume=$ers_id preflight_failed=seq37_startup_count want=1 got=$ers_n_start file=$ers_src" >&2
        return 1
    fi

    ers_n_bt=$(awk -v s="$RESUME_ANCHOR_SEQ" '
        /idma_batch_obs / && /part=time/ {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) n++
        }
        END { print n + 0 }' "$ers_src")
    case "$ers_n_bt" in
        ''|*[!0-9]*)
            echo "P4M: resume=$ers_id preflight_failed=seq37_batch_time_count_unreadable file=$ers_src" >&2
            return 1 ;;
    esac
    if [ "$ers_n_bt" != "1" ]; then
        echo "P4M: resume=$ers_id preflight_failed=seq37_batch_time_count want=1 got=$ers_n_bt file=$ers_src" >&2
        return 1
    fi

    if ! awk -v s="$RESUME_ANCHOR_SEQ" '
        /idma_batch_start / {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) { print $0; exit }
        }' "$ers_src" > "$ers_startup"; then
        echo "P4M: resume=$ers_id preflight_failed=seq37_startup_extract file=$ers_src" >&2
        return 1
    fi
    if ! awk -v s="$RESUME_ANCHOR_SEQ" '
        /idma_batch_obs / && /part=time/ {
            for (i = 1; i <= NF; i++)
                if ($i == ("seq=" s)) { print $0; exit }
        }' "$ers_src" > "$ers_batchtime"; then
        echo "P4M: resume=$ers_id preflight_failed=seq37_batch_time_extract file=$ers_src" >&2
        return 1
    fi
    return 0
}

# Reuse the normal production startup/batch-time/JSON checks on one extracted
# seq37 boundary. rcs_json may be empty when only the dmesg record is checked.
resume_check_seq37_record() {
    rcs_id=$1
    rcs_src=$2
    rcs_startup=$3
    rcs_batchtime=$4
    rcs_json=$5

    if ! extract_resume_seq37 "$rcs_id" "$rcs_src" "$rcs_startup" "$rcs_batchtime"; then
        return 1
    fi
    if ! rcs_sfields=$(verify_startup "$rcs_id" "$rcs_startup" "pair"); then
        return 1
    fi
    echo "P4M: resume=$rcs_id startup $rcs_sfields" >&2
    if ! verify_batch_time "$rcs_id" "$rcs_batchtime" "$LONG_TRANSFERS" "$A_DID"; then
        return 1
    fi
    rcs_anchor=$(int_of "$(dmget "$rcs_startup" a_begin_ns)")
    if [ "$rcs_anchor" != "$RESUME_ANCHOR_A_BEGIN_NS" ]; then
        echo "P4M: resume=$rcs_id preflight_failed=anchor_a_begin_ns got=$rcs_anchor want=$RESUME_ANCHOR_A_BEGIN_NS" >&2
        return 1
    fi
    if [ -n "$rcs_json" ]; then
        if ! check_case_json "$rcs_id" "$rcs_json" "p4m" "$LONG_TRANSFERS" "$A_DID" "$RESUME_ANCHOR_SEQ"; then
            return 1
        fi
    fi
    return 0
}

# Read-only resume35 preflight. It collects one current dmesg snapshot and checks
# that the archived seq37 boundary still exists before the first new DMA. It
# never edits the original output directory.
resume_preflight() {
    rp_dmesg="$OUT/resume-preflight.dmesg.raw"
    rp_startup="$OUT/resume-preflight-seq37.startup"
    rp_batchtime="$OUT/resume-preflight-seq37.batch_time"
    rp_old_startup="$OUT/resume-old25-seq37.startup"
    rp_old_batchtime="$OUT/resume-old25-seq37.batch_time"
    rp_orig_params="$RESUME_ORIGINAL/params.txt"
    rp_orig_json="$RESUME_ORIGINAL/$RESUME_ORIGINAL_CASE.json"
    rp_orig_dmesg="$RESUME_ORIGINAL/$RESUME_ORIGINAL_CASE.dmesg.raw"

    if [ "$kernel_release" != "$KERNEL_RESUME_EXACT" ]; then
        echo "P4M: resume35 preflight_failed=kernel_exact got=$kernel_release want=$KERNEL_RESUME_EXACT" >&2
        return 5
    fi
    case "$kernel_release" in
        *"$KERNEL_RESUME_MATCH"*) ;;
        *)
            echo "P4M: resume35 preflight_failed=kernel_match got=$kernel_release want=*$KERNEL_RESUME_MATCH*" >&2
            return 5 ;;
    esac

    if ! dmesg > "$rp_dmesg" 2> "$OUT/resume-preflight.dmesg.err"; then
        echo "P4M: resume35 preflight_failed=dmesg_collection" >&2
        return 4
    fi
    rp_max=$(startup_max_seq "$rp_dmesg" "resume35")
    rp_max_rc=$?
    if [ "$rp_max_rc" -ne 0 ]; then
        if [ -n "$rp_max" ]; then
            printf '%s\n' "$rp_max" >&2
        else
            echo "P4M: resume35 preflight_failed=startup_max_seq_unreadable file=$rp_dmesg" >&2
        fi
        return 5
    fi
    case "$rp_max" in
        ''|*[!0-9]*)
            echo "P4M: resume35 preflight_failed=startup_max_seq_unreadable file=$rp_dmesg" >&2
            return 5 ;;
    esac
    if [ "$rp_max" != "$RESUME_ANCHOR_SEQ" ]; then
        echo "P4M: resume35 preflight_failed=startup_max_seq want=$RESUME_ANCHOR_SEQ got=$rp_max; stop for manual review, no continuation" >&2
        return 5
    fi

    if ! resume_check_seq37_record "resume-current" "$rp_dmesg" "$rp_startup" "$rp_batchtime" ""; then
        return 5
    fi

    if [ ! -d "$RESUME_ORIGINAL" ]; then
        echo "P4M: resume35 preflight_failed=missing_original_dir path=$RESUME_ORIGINAL" >&2
        return 5
    fi
    if [ ! -r "$rp_orig_params" ]; then
        echo "P4M: resume35 preflight_failed=missing_original_params path=$rp_orig_params" >&2
        return 5
    fi
    rp_old_kernel=$(awk -F= '$1 == "kernel_release" { print $2; exit }' "$rp_orig_params")
    if [ "$rp_old_kernel" != "$KERNEL_RESUME_EXACT" ]; then
        echo "P4M: resume35 preflight_failed=original_kernel got=$rp_old_kernel want=$KERNEL_RESUME_EXACT" >&2
        return 5
    fi

    if [ ! -r "$rp_orig_json" ]; then
        echo "P4M: resume35 preflight_failed=missing_old25_json path=$rp_orig_json" >&2
        return 5
    fi
    if [ ! -r "$rp_orig_dmesg" ]; then
        echo "P4M: resume35 preflight_failed=missing_old25_dmesg path=$rp_orig_dmesg" >&2
        return 5
    fi
    if ! resume_check_seq37_record "resume-old25" "$rp_orig_dmesg" "$rp_old_startup" "$rp_old_batchtime" "$rp_orig_json"; then
        return 5
    fi

    {
        echo "resume35_preflight=ok"
        echo "original_run_id=$RESUME_ORIGINAL_ID"
        echo "original_output=$RESUME_ORIGINAL"
        echo "original_case=$RESUME_ORIGINAL_CASE"
        echo "anchor_seq=$RESUME_ANCHOR_SEQ"
        echo "anchor_a_begin_ns=$RESUME_ANCHOR_A_BEGIN_NS"
        echo "kernel_release=$kernel_release"
        echo "current_dmesg=$rp_dmesg"
        if [ -r /proc/sys/kernel/random/boot_id ]; then
            printf 'current_boot_id='
            cat /proc/sys/kernel/random/boot_id 2>/dev/null || echo unknown
        else
            echo "current_boot_id=unknown"
        fi
        if [ -r /proc/uptime ]; then
            printf 'current_uptime='
            cat /proc/uptime 2>/dev/null || echo unknown
        else
            echo "current_uptime=unknown"
        fi
    } > "$OUT/resume35-preflight.txt" || {
        echo "P4M: resume35 preflight_failed=metadata_write" >&2
        return 4
    }
    return 0
}

run_formal_resume() {
    run_case "formal-b09-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b09-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_formal_triplet 10 0 2000 1000 || return $?
    run_formal_triplet 11 2000 1000 0 || return $?
    run_formal_triplet 12 1000 0 2000 || return $?
    run_formal_triplet 13 0 1000 2000 || return $?
    run_formal_triplet 14 1000 2000 0 || return $?
    run_formal_triplet 15 2000 0 1000 || return $?
    run_formal_triplet 16 0 2000 1000 || return $?
    run_formal_triplet 17 2000 1000 0 || return $?
    run_formal_triplet 18 1000 0 2000 || return $?
    run_formal_triplet 19 0 1000 2000 || return $?
    run_formal_triplet 20 2000 1000 0 || return $?
    return 0
}


# ---------------------------------------------------------------------------
# New-boot remaining29 segment (independent new boot; NOT a same-boot resume).
#
# The original resume35 seq37 anchor is never read or used and the old modes
# are unreachable: mode selection and dispatch accept only remaining29. This
# segment never claims the full 60-case run.
# ---------------------------------------------------------------------------

# Frozen new-boot remaining flat cases 32..60 of the original formal60 plan:
# formal-b11-g1000, formal-b11-g0, then b12..b20 unchanged in the original
# order. 29 P4M trials, 4096 transfers, warmup 256, 4096-byte chunk. Flat
# cases 1..31 are never replayed here. Gap counts: 0:10, 1000:10, 2000:9.
run_remaining29() {
    run_case "formal-b11-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b11-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b12-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b12-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b12-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b13-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b13-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b13-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b14-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b14-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b14-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b15-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b15-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b15-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b16-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b16-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b16-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b17-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b17-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b17-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b18-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b18-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b18-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b19-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b19-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b19-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b20-g2000" "P8g2000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b20-g1000" "P8g1000" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    run_case "formal-b20-g0" "P8g0" "$LONG_TRANSFERS" "$LONG_WARMUP" || return $?
    return 0
}

# New-boot preflight, run after the generic command/uname/taint/path_observe
# gates and before the first idma_experiment call. Fail closed: any mismatch
# returns nonzero, so DMA never starts on the wrong kernel, the wrong boot,
# dirty taint, a non-Y path_observe, or a dmesg that already carries an
# idma_batch_start record (that would mean this is not a fresh boot segment).
newboot_preflight() {
    nbp_dmesg="$OUT/newboot-preflight.dmesg.raw"

    if [ "$kernel_release" != "$KERNEL_NEWBOOT_EXACT" ]; then
        echo "P4M: remaining29 preflight_failed=kernel_exact got=$kernel_release want=$KERNEL_NEWBOOT_EXACT" >&2
        return 5
    fi
    case "$kernel_release" in
        *"$KERNEL_NEWBOOT_MATCH"*) ;;
        *)
            echo "P4M: remaining29 preflight_failed=kernel_match got=$kernel_release want=*$KERNEL_NEWBOOT_MATCH*" >&2
            return 5 ;;
    esac

    if [ ! -r /proc/sys/kernel/random/boot_id ]; then
        echo "P4M: remaining29 preflight_failed=boot_id_unreadable path=/proc/sys/kernel/random/boot_id" >&2
        return 5
    fi
    nbp_boot_id=$(cat /proc/sys/kernel/random/boot_id 2>/dev/null)
    if [ "$nbp_boot_id" != "$NEWBOOT_BOOT_ID" ]; then
        echo "P4M: remaining29 preflight_failed=boot_id got=$nbp_boot_id want=$NEWBOOT_BOOT_ID" >&2
        return 5
    fi

    nbp_taint=$(read_taint)
    if [ "$nbp_taint" != "0" ]; then
        echo "P4M: remaining29 preflight_failed=taint value=$nbp_taint refusing before any DMA" >&2
        return 3
    fi
    nbp_path_observe=$(read_path_observe)
    if [ "$nbp_path_observe" != "Y" ]; then
        echo "P4M: remaining29 preflight_failed=path_observe value=$nbp_path_observe refusing before any DMA (--p4m cases require Y)" >&2
        return 3
    fi

    if ! dmesg > "$nbp_dmesg" 2> "$OUT/newboot-preflight.dmesg.err"; then
        echo "P4M: remaining29 preflight_failed=dmesg_collection" >&2
        return 4
    fi
    nbp_max=$(startup_max_seq "$nbp_dmesg" "remaining29")
    nbp_max_rc=$?
    if [ "$nbp_max_rc" -ne 0 ]; then
        if [ -n "$nbp_max" ]; then
            printf '%s\n' "$nbp_max" >&2
        else
            echo "P4M: remaining29 preflight_failed=startup_max_seq_unreadable file=$nbp_dmesg" >&2
        fi
        return 5
    fi
    case "$nbp_max" in
        ''|*[!0-9]*)
            echo "P4M: remaining29 preflight_failed=startup_max_seq_unreadable file=$nbp_dmesg" >&2
            return 5 ;;
    esac
    if [ "$nbp_max" != "$NEWBOOT_FIRST_STARTUP_MAX_SEQ" ]; then
        echo "P4M: remaining29 preflight_failed=first_startup_max_seq want=$NEWBOOT_FIRST_STARTUP_MAX_SEQ got=$nbp_max; not a fresh boot segment, stop for manual review" >&2
        return 5
    fi

    {
        echo "remaining29_preflight=ok"
        echo "new_boot_segment=1"
        echo "boot_id=$nbp_boot_id"
        echo "kernel_release=$kernel_release"
        echo "first_startup_max_seq=$nbp_max"
        echo "taint=$nbp_taint path_observe=$nbp_path_observe"
        echo "original_resume35_anchor_used=0"
        echo "full60_claim=0"
        echo "current_dmesg=$nbp_dmesg"
    } > "$OUT/remaining29-preflight.txt" || {
        echo "P4M: remaining29 preflight_failed=metadata_write" >&2
        return 4
    }
    return 0
}

collection_failed=0
cases_done=0

trap cleanup EXIT
trap 'exit 129' HUP
trap 'exit 130' INT
trap 'exit 143' TERM

cleanup() {
    rc=$?
    trap - EXIT HUP INT TERM
    save_dmesg || collection_failed=1
    save_taint || collection_failed=1
    if [ "$collection_failed" -ne 0 ] && [ "$rc" -eq 0 ]; then
        rc=4
    fi
    echo "P4M: final_exit=$rc collection_failed=$collection_failed mode=$mode cases_done=$cases_done total=$TOTAL_CASES output=$OUT" >&2
    if [ "$rc" -eq 0 ] && [ "$cases_done" -eq "$TOTAL_CASES" ]; then
        if ! echo "P4M: complete ok mode=$mode cases=$cases_done total=$TOTAL_CASES output=$OUT"; then
            echo "P4M: complete marker write failed" >&2
            rc=4
        fi
    fi
    if [ "$rc" -eq 0 ] && [ "$mode" = "remaining29" ] && [ "$cases_done" -eq "$TOTAL_CASES" ]; then
        if ! echo "P4M: remaining29_segment_complete cases=29 total=29 full_formal60=not_claimed new_boot_segment=1 previous_online24_plus_offline1_plus_offline6_pending_audit=1 boot_id=$NEWBOOT_BOOT_ID output=$OUT"; then
            echo "P4M: remaining29 segment marker write failed" >&2
            rc=4
        fi
    fi
    exit "$rc"
}

if ! : > "$OUT/argv.txt"; then
    fatal "argv write failed: $OUT/argv.txt"
fi
if ! : > "$OUT/path_observe.txt"; then
    fatal "path_observe record write failed: $OUT/path_observe.txt"
fi

if ! {
    echo "mode=$mode"
    echo "output=$OUT"
    echo "kernel_old_match=$KERNEL_OLD_MATCH"
    echo "kernel_expect=newer than the old baseline; the new hash is not hardcoded"
    echo "cases_total=$TOTAL_CASES"
    if [ "$mode" = "remaining29" ]; then
        echo "new_boot_segment=1"
        echo "previous_online24_plus_offline1_plus_offline6_pending_audit=1"
        echo "previous_online_cases=24 previous_offline_cases=1 previous_pending_audit_cases=6"
        echo "remaining29_first_flat=32 remaining29_last_flat=60 cases=29"
        echo "remaining29_order=formal-b11-g1000 formal-b11-g0 then b12..b20 unchanged"
        echo "remaining29_gap_counts=0:10 1000:10 2000:9"
        echo "remaining29_full60_claim=0"
    fi
    echo "watchdog_seconds=$WATCHDOG driver_timeout_ms=$DRIVER_TIMEOUT_MS"
    echo "short=4x transfers=$SHORT_TRANSFERS warmup=$SHORT_WARMUP chunk=$CHUNK"
    echo "compare=8x transfers=$LONG_TRANSFERS warmup=$LONG_WARMUP chunk=$CHUNK"
    echo "formal60=20 blocks x 3 P4M trials, gaps 0/1000/2000 once per block, transfers=$LONG_TRANSFERS warmup=$LONG_WARMUP chunk=$CHUNK; requires_short_block=0 requires_compare_block=0"
    echo "victim_device=$VICTIM_DEVICE victim_did=$V_DID aggressor_did=$A_DID no_aggressor=$NO_AGGRESSOR"
    echo "require_path_observe_Y=1 require_observe_Y=0"
} > "$OUT/input.txt"; then
    fatal "input write failed: $OUT/input.txt"
fi

if ! {
    echo "P4M software batch-start frozen plan ($mode)"
    echo "order_short=S P1g0 P8g0 P8g1000"
    echo "order_compare=B8 P8g0 P8g0 B8 B8 P8g0 P8g0 B8"
    echo "formal60=20 blocks x 3 P4M trials, gaps 0/1000/2000 once per block, transfers=$LONG_TRANSFERS warmup=$LONG_WARMUP chunk=$CHUNK; requires_short_block=0 requires_compare_block=0"
    echo "order_formal60=20 blocks x 3 gaps; first 18 = three cycles of (0 1000 2000),(1000 2000 0),(2000 0 1000),(0 2000 1000),(2000 1000 0),(1000 0 2000); b19=(0 1000 2000); b20=(2000 1000 0)"
    echo "condition_specs (kind mode argv):"
    for cond in S P1g0 P8g0 P8g1000 P8g2000 B8; do
        echo "  $cond $(condition_spec "$cond")"
    done
    echo "cli_json_schema=nested: success + result{...} + p4m{...} for --p4m; no top-level batch_polled/status/v_issued/time_valid"
    echo "batch_time_record=idma_batch_obs part=time carries valid/status/v_did/a_did/issued/done/batch_polled"
    echo "all_mode_compare_block_runs_only_when_short_block_passed=1"
    if [ "$mode" = "remaining29" ]; then
        echo "order_remaining29=formal-b11-g1000 formal-b11-g0 then b12..b20 unchanged"
        echo "remaining29_flat_start=32 remaining29_flat_end=60 cases=29 gaps0=10 gaps1000=10 gaps2000=9"
        echo "remaining29_no_replay=flat cases 1..31 (formal-b01-g0 .. formal-b11-g2000) are never rerun"
        echo "remaining29_independent_new_boot=1 original_resume35_anchor_used=0 full60_claim=0"
        echo "remaining29_requires_newboot_preflight=boot_id_$NEWBOOT_BOOT_ID kernel_$KERNEL_NEWBOOT_EXACT first_startup_max_seq=$NEWBOOT_FIRST_STARTUP_MAX_SEQ"
    fi
} > "$OUT/matrix.txt"; then
    fatal "matrix write failed: $OUT/matrix.txt"
fi

kernel_release=$(uname -r 2>/dev/null)
kernel_rc=$?
kernel_all=$(uname -a 2>/dev/null)
observe=$(read_observe)
path_observe=$(read_path_observe)
taint_baseline=$(read_taint)

if ! {
    echo "runner=linux_p4m_remaining29.sh"
    echo "new_boot_segment=1"
    echo "mode=$mode"
    echo "output=$OUT"
    echo "date_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo unknown)"
    echo "time_format=UTC ISO-8601 seconds (date -u +%Y-%m-%dT%H:%M:%SZ)"
    echo "case_time_source=dmesg default kernel timestamp; no per-case wall clock is stored"
    echo "uname=$kernel_all"
    echo "kernel_release=$kernel_release"
    echo "kernel_old_match=$KERNEL_OLD_MATCH"
    echo "taint_baseline=$taint_baseline"
    echo "taint_path=$TAINT_PATH"
    echo "observe=$observe"
    echo "observe_path=$OBSERVE_PATH"
    echo "path_observe=$path_observe"
    echo "path_observe_path=$PATH_OBSERVE_PATH"
    echo "path=$PATH"
    echo "watchdog_seconds=$WATCHDOG driver_timeout_ms=$DRIVER_TIMEOUT_MS"
    echo "chunk=$CHUNK victim_device=$VICTIM_DEVICE victim_did=$V_DID aggressor_did=$A_DID"
    echo "short_transfers=$SHORT_TRANSFERS short_warmup=$SHORT_WARMUP"
    echo "compare_transfers=$LONG_TRANSFERS compare_warmup=$LONG_WARMUP"
    echo "formal60=20 blocks x 3 P4M trials, transfers=$LONG_TRANSFERS warmup=$LONG_WARMUP chunk=$CHUNK, requires_short_block=0 requires_compare_block=0"
    echo "cases_total=$TOTAL_CASES"
    if [ "$mode" = "remaining29" ]; then
        echo "new_boot_segment=1"
        echo "previous_online24_plus_offline1_plus_offline6_pending_audit=1"
        echo "previous_online_cases=24 previous_offline_cases=1 previous_pending_audit_cases=6"
        echo "full60_claim=0"
        echo "boot_id=$NEWBOOT_BOOT_ID"
        echo "remaining29_first_flat=32 remaining29_last_flat=60 cases=29"
        echo "remaining29_order=formal-b11-g1000 formal-b11-g0 then b12..b20 unchanged"
        echo "remaining29_gap_counts=0:10 1000:10 2000:9"
        echo "remaining29_kernel_exact=$KERNEL_NEWBOOT_EXACT"
        echo "remaining29_requires_newboot_preflight=1"
        echo "original_resume35_anchor_used=0"
    fi
    echo "require_path_observe_Y=1 require_observe_Y=0"
} > "$OUT/params.txt"; then
    fatal "params write failed: $OUT/params.txt"
fi

for cmd in platform-timeout idma_experiment dmesg uname awk; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
        echo "P4M: missing command: $cmd" >&2
        exit 127
    fi
done

if [ "$kernel_rc" -ne 0 ] || [ -z "$kernel_release" ]; then
    fatal "uname -r failed; refusing before any DMA"
fi

case "$kernel_release" in
    *"$KERNEL_OLD_MATCH"*)
        fatal "old baseline kernel running ($kernel_release matches $KERNEL_OLD_MATCH); refusing before any DMA"
        ;;
esac

printf 'preflight observe=%s path_observe=%s\n' "$observe" "$path_observe" >> "$OUT/path_observe.txt"
if [ "$plan_has_p4m" = "1" ] && [ "$path_observe" != "Y" ]; then
    echo "P4M: path_observe gate failed value=$path_observe ($PATH_OBSERVE_PATH); --p4m cases require Y before any DMA" >&2
    exit 3
fi
if [ "$taint_baseline" != "0" ]; then
    echo "P4M: taint gate failed value=$taint_baseline; refusing before any DMA" >&2
    exit 3
fi

case "$mode" in
    remaining29)
        newboot_preflight || exit $?
        run_remaining29 || exit $?
        ;;
esac

exit 0
